# ==============================================================================
# MOTOR PRINCIPAL: PROGRAMA PERFECTO XVIEW+ (ZTE ZXV10 B866V2 - S905X2 G12A)
# Fusión integral de todas las herramientas de la memoria USB + hallazgos REA
# Regla absoluta: 100% Externo (Cero tornillos, Cero TTL, Protección Widevine L1)
# ==============================================================================

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ErrorActionPreference = "Continue"

$ROOT_DIR   = Split-Path -Parent $PSScriptRoot
$MOTOR_DIR  = Join-Path $ROOT_DIR "1_HERRAMIENTAS_MOTOR"
$APKS_DIR   = Join-Path $ROOT_DIR "2_APKS_LIBERACION_Y_TV"
$KEYS_DIR   = Join-Path $ROOT_DIR "3_LLAVES_USB_PARA_LA_CAJA"
$DRV_DIR    = Join-Path $ROOT_DIR "4_DRIVERS_Y_GUI_WINDOWS"
$FW_DIR     = Join-Path $ROOT_DIR "5_FIRMWARE_SEGURO_B866V2"

$ADB        = Join-Path $MOTOR_DIR "adb.exe"
$FASTBOOT   = Join-Path $MOTOR_DIR "fastboot_moderno.exe"
if (-not (Test-Path $FASTBOOT)) { $FASTBOOT = Join-Path $MOTOR_DIR "fastboot.exe" }
$ADNL       = Join-Path $MOTOR_DIR "adnl.exe"
$UPDATE     = Join-Path $MOTOR_DIR "update.exe"

$Global:ADB_TARGET_ARGS = @()
$Global:CONNECTED_IP    = ""

function Invoke-Adb {
    param([string[]]$Arguments)
    $allArgs = @()
    if ($Global:ADB_TARGET_ARGS.Count -gt 0) { $allArgs += $Global:ADB_TARGET_ARGS }
    $allArgs += $Arguments
    & $ADB @allArgs
}

function Get-BoxConnectionState {
    $state = [ordered]@{
        UsbHardwareMode = "Ninguno detectado por cable USB directo"
        AdbDevices      = @()
        FastbootDevices = @()
        AdnlDevices     = @()
    }

    # 1. Escanear PnP USB (VID_18D1 Google/Android, VID_19D2 ZTE, VID_1B8E Amlogic WorldCup)
    try {
        $pnp = Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object {
            $_.DeviceID -match "VID_18D1|VID_19D2|VID_1B8E"
        }
        foreach ($dev in $pnp) {
            if ($dev.DeviceID -match "PID_4EE2") { $state.UsbHardwareMode = "ADB USB Activo (PID_4EE2)" }
            elseif ($dev.DeviceID -match "PID_4EE7") { $state.UsbHardwareMode = "Recovery Fastbootd (PID_4EE7)" }
            elseif ($dev.DeviceID -match "PID_0D02") { $state.UsbHardwareMode = "U-Boot Fastboot Bootloader (PID_0D02)" }
            elseif ($dev.DeviceID -match "PID_4EE1") { $state.UsbHardwareMode = "Modo MTP Android Normal (PID_4EE1 - Falta activar Depuracion USB)" }
            elseif ($dev.DeviceID -match "VID_1B8E") { $state.UsbHardwareMode = "Amlogic WorldCup / DNL Burn Mode (VID_1B8E)" }
        }
    } catch {}

    # 2. Escanear ADB
    if (Test-Path $ADB) {
        $adbOut = & $ADB devices 2>$null
        foreach ($line in $adbOut) {
            if ($line -match "^(\S+)\s+(device|unauthorized|offline)$") {
                $state.AdbDevices += "$($Matches[1]) [$($Matches[2])]"
            }
        }
    }

    # 3. Escanear Fastboot
    if (Test-Path $FASTBOOT) {
        $fbOut = & $FASTBOOT devices 2>$null
        foreach ($line in $fbOut) {
            if ($line -match "^(\S+)\s+fastboot") {
                $state.FastbootDevices += $Matches[1]
            }
        }
    }

    return $state
}

function Show-Banner {
    Clear-Host
    Write-Host "╔══════════════════════════════════════════════════════════════════════════════╗" -ForegroundColor Cyan
    Write-Host "║         PROGRAMA PERFECTO - MEGACABLE XVIEW+ (ZTE ZXV10 B866V2)              ║" -ForegroundColor Cyan
    Write-Host "║    Fusión Total USB + ADB + Fastboot + ADNL + Launchers + Desbloqueo ZTE     ║" -ForegroundColor Cyan
    Write-Host "║     Regla: 100% Externo Sin Abrir Tornillos | Protección Widevine L1/MAC     ║" -ForegroundColor Cyan
    Write-Host "╚══════════════════════════════════════════════════════════════════════════════╝" -ForegroundColor Cyan

    $st = Get-BoxConnectionState
    Write-Host ""
    Write-Host " [RADAR DE CONEXIÓN EN TIEMPO REAL]" -ForegroundColor Yellow
    Write-Host "  • Cable USB Físico : $($st.UsbHardwareMode)" -ForegroundColor Gray
    if ($st.AdbDevices.Count -gt 0) {
        Write-Host "  • Dispositivos ADB : $($st.AdbDevices -join ', ')" -ForegroundColor Green
    } else {
        Write-Host "  • Dispositivos ADB : Ninguno conectado (Usa Opción 0 para conectar por IP o activa Depuración USB)" -ForegroundColor DarkGray
    }
    if ($st.FastbootDevices.Count -gt 0) {
        Write-Host "  • Modo Fastboot    : $($st.FastbootDevices -join ', ')" -ForegroundColor Green
    } else {
        Write-Host "  • Modo Fastboot    : Ninguno en espera" -ForegroundColor DarkGray
    }
    Write-Host "────────────────────────────────────────────────────────────────────────────────" -ForegroundColor DarkCyan
}

function Connect-AdbTarget {
    Write-Host ""
    Write-Host "=== CONECTAR CAJA POR RED LOCAL (WI-FI / ETHERNET) O CABLE USB ===" -ForegroundColor Yellow
    Write-Host "NOTA: Si usas router/módem, desconecta el cable de Internet del módem para evitar" -ForegroundColor Gray
    Write-Host "      que aparezca la pantalla azul de Megacable mientras activas Depuración USB." -ForegroundColor Gray
    Write-Host ""
    $ip = Read-Host "Escribe la IP de la caja (ej. 192.168.0.47) o presiona ENTER para usar Cable USB"
    if (-not [string]::IsNullOrWhiteSpace($ip)) {
        if ($ip -notmatch ":") { $ip = "${ip}:5555" }
        Write-Host "[+] Conectando por ADB a $ip ..." -ForegroundColor Cyan
        & $ADB connect $ip
        $Global:ADB_TARGET_ARGS = @("-s", $ip)
        $Global:CONNECTED_IP = $ip
        Write-Host "[!] Revisa tu TV y acepta el cartel '¿Permitir depuración por USB?' marcando 'Permitir siempre'." -ForegroundColor Green
    } else {
        $Global:ADB_TARGET_ARGS = @()
        $Global:CONNECTED_IP = ""
        & $ADB devices
    }
    Read-Host "`nPresiona ENTER para volver al menú"
}

