$MOTOR_DIR  = Join-Path $ROOT_DIR "1_HERRAMIENTAS_MOTOR"
$APKS_DIR   = Join-Path $ROOT_DIR "2_APKS_LIBERACION_Y_TV"
$KEYS_DIR   = Join-Path $ROOT_DIR "3_LLAVES_USB_PARA_LA_CAJA"
