$FW_DIR     = Join-Path $ROOT_DIR "5_FIRMWARE_SEGURO_B866V2"

$ADB        = Join-Path $MOTOR_DIR "adb.exe"
$FASTBOOT   = Join-Path $MOTOR_DIR "fastboot_moderno.exe"
if (-not (Test-Path $FASTBOOT)) { $FASTBOOT = Join-Path $MOTOR_DIR "fastboot.exe" }
$ADNL       = Join-Path $MOTOR_DIR "adnl.exe"
$UPDATE     = Join-Path $MOTOR_DIR "update.exe"

$Global:ADB_TARGET_ARGS = @()
$Global:CONNECTED_IP    = ""

function Invoke-Adb {
    param([string[]]$Arguments)
    $allArgs = @()
    if ($Global:ADB_TARGET_ARGS.Count -gt 0) { $allArgs += $Global:ADB_TARGET_ARGS }
    $allArgs += $Arguments
    & $ADB @allArgs
}

function Get-BoxConnectionState {
    $state = [ordered]@{
        UsbHardwareMode = "Ninguno detectado por cable USB directo"
        AdbDevices      = @()
        FastbootDevices = @()
        AdnlDevices     = @()
    }

    # 1. Escanear PnP USB (VID_18D1 Google/Android, VID_19D2 ZTE, VID_1B8E Amlogic WorldCup)
    try {
        $pnp = Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue | Where-Object {
            $_.DeviceID -match "VID_18D1|VID_19D2|VID_1B8E"
        }
        foreach ($dev in $pnp) {
            if ($dev.DeviceID -match "PID_4EE2") { $state.UsbHardwareMode = "ADB USB Activo (PID_4EE2)" }
            elseif ($dev.DeviceID -match "PID_4EE7") { $state.UsbHardwareMode = "Recovery Fastbootd (PID_4EE7)" }
            elseif ($dev.DeviceID -match "PID_0D02") { $state.UsbHardwareMode = "U-Boot Fastboot Bootloader (PID_0D02)" }
            elseif ($dev.DeviceID -match "PID_4EE1") { $state.UsbHardwareMode = "Modo MTP Android Normal (PID_4EE1 - Falta activar Depuracion USB)" }
            elseif ($dev.DeviceID -match "VID_1B8E") { $state.UsbHardwareMode = "Amlogic WorldCup / DNL Burn Mode (VID_1B8E)" }
        }
    } catch {}

    # 2. Escanear ADB
    if (Test-Path $ADB) {
        $adbOut = & $ADB devices 2>$null
        foreach ($line in $adbOut) {
            if ($line -match "^(\S+)\s+(device|unauthorized|offline)$") {
                $state.AdbDevices += "$($Matches[1]) [$($Matches[2])]"
            }
        }
    }

    # 3. Escanear Fastboot
    if (Test-Path $FASTBOOT) {
        $fbOut = & $FASTBOOT devices 2>$null
        foreach ($line in $fbOut) {
            if ($line -match "^(\S+)\s+fastboot") {
                $state.FastbootDevices += $Matches[1]
            }
        }
    }

    return $state
}

