    Write-Host "   OPCION 3: PUENTE A BOOTLOADER FASTBOOT + ANTI-WATCHDOG + DESBLOQUEO OTG     " -ForegroundColor Yellow
    Write-Host "================================================================================" -ForegroundColor Yellow
    Write-Host "Esta funcion fusiona 'Comandos.txt', 'Tools cek slot' y nuestro enganche Anti-Watchdog:" -ForegroundColor Gray
