    Write-Host "    U-Boot Fastboot real (PID_0D02) y apaga el Watchdog de 14 segundos al instante." -ForegroundColor Gray
    Write-Host ""

    $st = Get-BoxConnectionState
    if ($st.AdbDevices.Count -gt 0) {
        Write-Host "[+] Caja detectada en ADB. Enviando 'adb reboot bootloader'..." -ForegroundColor Cyan
