    }

    Write-Host "[*] Esperando activamente a la caja en USB Fastboot / Fastbootd (Presiona Ctrl+C para cancelar)..." -ForegroundColor Cyan
    while ($true) {
        $fbOut = & $FASTBOOT devices 2>$null
        if ($fbOut -match "fastboot") {
            $isUserspace = & $FASTBOOT getvar is-userspace 2>&1
            if ($isUserspace -match "yes") {
