function Invoke-FastbootBridgeAndUnlock {
    Write-Host ""
    Write-Host "================================================================================" -ForegroundColor Yellow
    Write-Host "   OPCION 3: PUENTE A BOOTLOADER FASTBOOT + ANTI-WATCHDOG + DESBLOQUEO OTG     " -ForegroundColor Yellow
    Write-Host "================================================================================" -ForegroundColor Yellow
    Write-Host "Esta funcion fusiona 'Comandos.txt', 'Tools cek slot' y nuestro enganche Anti-Watchdog:" -ForegroundColor Gray
    Write-Host "  * Si la caja esta en ADB -> la envia automaticamente a U-Boot Fastboot." -ForegroundColor Gray
    Write-Host "  * Si la caja esta en Recovery 'Enter fastboot' (fastbootd PID_4EE7) -> la salta a" -ForegroundColor Gray
    Write-Host "    U-Boot Fastboot real (PID_0D02) y apaga el Watchdog de 14 segundos al instante." -ForegroundColor Gray
    Write-Host ""

    $st = Get-BoxConnectionState
    if ($st.AdbDevices.Count -gt 0) {
        Write-Host "[+] Caja detectada en ADB. Enviando 'adb reboot bootloader'..." -ForegroundColor Cyan
        Invoke-Adb @("reboot", "bootloader")
    }

    Write-Host "[*] Esperando activamente a la caja en USB Fastboot / Fastbootd (Presiona Ctrl+C para cancelar)..." -ForegroundColor Cyan
    while ($true) {
        $fbOut = & $FASTBOOT devices 2>$null
        if ($fbOut -match "fastboot") {
            $isUserspace = & $FASTBOOT getvar is-userspace 2>&1
            if ($isUserspace -match "yes") {
                Write-Host "[!] Detectado Recovery Fastbootd (PID_4EE7). Saltando a U-Boot Bootloader real..." -ForegroundColor Yellow
                & $FASTBOOT reboot bootloader
                Start-Sleep -Milliseconds 500
                continue
            }
            Write-Host "[+] Caja atrapada en U-Boot Fastboot! Apagando Watchdog y desbloqueando..." -ForegroundColor Green
            & $FASTBOOT oem "watchdog off"
            & $FASTBOOT flashing unlock_critical
            & $FASTBOOT flashing unlock
            & $FASTBOOT oem "setenv lock 10100000;save"
            & $FASTBOOT oem "setenv otg_device 1;save"
            & $FASTBOOT oem "saveenv"
            & $FASTBOOT getvar unlocked
            Write-Host "[OK] Bootloader desbloqueado, Watchdog apagado y USB OTG activado." -ForegroundColor Green
            break
        }
        Start-Sleep -Milliseconds 250
    }
    Read-Host "`nPresiona ENTER para volver al menu"
}

