    Write-Host "================================================================================" -ForegroundColor Cyan
    Write-Host "   OPCION 5: MOTOR AMLOGIC DNL / WORLDCUP (adnl.exe + update.exe VID_1B8E)      " -ForegroundColor Cyan
    Write-Host "================================================================================" -ForegroundColor Cyan
