    & $FASTBOOT flash cache (Join-Path $FW_DIR "cache_ext4.img")

    Write-Host "[12/12] Limpiando userdata y reiniciando..." -ForegroundColor Cyan
    & $FASTBOOT erase userdata
    & $FASTBOOT reboot

    Write-Host "`n[COMPLETADO!] Tu caja B866V2 arrancara con Android 12 liberado (con ADB ya activo de fabrica y Widevine L1 intacto)." -ForegroundColor Green
    Read-Host "`nPresiona ENTER para volver al menu"
