        // ==============================================================================
        // ESCANER AUTOMATICO DE SUBRED LOCAL PARA ENCONTRAR LA CAJA EN PUERTO 5555
        // ==============================================================================
        static bool ScanLocalNetworkForBoxAdb()
        {
            LogEvent("NET_SCAN", "Iniciando escaneo rapido de subred local para puerto ADB 5555...");
            WriteColor("[*] Escaneando red local (Wi-Fi / Ethernet) en busca de la caja Xview+ (:5555)...", ConsoleColor.Cyan);

            List<string> prefixes = new List<string>();
            try
            {
                foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
                {
                    if (ni.OperationalStatus != OperationalStatus.Up ||
                        ni.NetworkInterfaceType == NetworkInterfaceType.Loopback)
                        continue;

                    foreach (UnicastIPAddressInformation ip in ni.GetIPProperties().UnicastAddresses)
                    {
                        if (ip.Address.AddressFamily == AddressFamily.InterNetwork)
                        {
                            byte[] b = ip.Address.GetAddressBytes();
                            if (b[0] == 192 || b[0] == 10 || b[0] == 172)
                            {
                                string pref = string.Format("{0}.{1}.{2}.", b[0], b[1], b[2]);
                                if (!prefixes.Contains(pref)) prefixes.Add(pref);
                            }
                        }
                    }
                }
            }
            catch { }

            if (prefixes.Count == 0)
            {
                prefixes.Add("192.168.0.");
                prefixes.Add("192.168.1.");
            }

            ConcurrentBag<string> openIps = new ConcurrentBag<string>();
            foreach (string prefix in prefixes)
            {
                WriteColor("    -> Sondeando subred " + prefix + "1-254 (puerto 5555)...", ConsoleColor.Gray);
                Parallel.For(1, 255, new ParallelOptions { MaxDegreeOfParallelism = 64 }, i =>
                {
                    string candidateIp = prefix + i;
                    try
                    {
                        using (TcpClient tcp = new TcpClient())
                        {
                            IAsyncResult ar = tcp.BeginConnect(candidateIp, 5555, null, null);
                            if (ar.AsyncWaitHandle.WaitOne(220))
                            {
                                tcp.EndConnect(ar);
                                openIps.Add(candidateIp);
                            }
                        }
                    }
                    catch { }
                });
            }

            foreach (string foundIp in openIps)
            {
                string target = foundIp + ":5555";
                WriteColor("    [+] Dispositivo con puerto 5555 abierto encontrado en: " + target, ConsoleColor.Green);
                LogEvent("NET_SCAN_HIT", "Puerto 5555 abierto en " + target);
                ToolResult conn = InvokeToolSafe(ADB_EXE, "connect " + target, 4000, true);
                Thread.Sleep(500);
                ToolResult devCheck = InvokeToolSafe(ADB_EXE, "devices", 2000, true);
                if (Regex.IsMatch(devCheck.Output, Regex.Escape(foundIp) + @"(?::5555)?\s+device\b"))
                {
                    CONNECTED_IP = target;
                    WriteColor("    [OK] Sesion ADB autorizada establecida con " + target + "!", ConsoleColor.Green);
                    return true;
                }
                else if (Regex.IsMatch(devCheck.Output, Regex.Escape(foundIp) + @"(?::5555)?\s+unauthorized"))
                {
                    CONNECTED_IP = target;
                    WriteColor("    [!] Caja encontrada en " + target + ". Acepta el permiso de Depuracion en la TV!", ConsoleColor.Yellow);
                    for (int w = 0; w < 12; w++)
                    {
                        Thread.Sleep(1500);
                        ToolResult reCheck = InvokeToolSafe(ADB_EXE, "devices", 2000, false);
                        if (Regex.IsMatch(reCheck.Output, Regex.Escape(foundIp) + @"(?::5555)?\s+device\b"))
                        {
                            WriteColor("    [OK] Permiso aceptado en la TV!", ConsoleColor.Green);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

