                ExecuteLiberatedXviewFirmwareUiTransformation();
            }
            return false;
        }

        static void WaitAndCatchAdbAfterReboot(int secondsToWait)
        {
            WriteColor("[*] Esperando a que la caja termine de encender (" + secondsToWait + "s) mientras buscamos ADB por USB y Red...", ConsoleColor.Cyan);
            Stopwatch sw = Stopwatch.StartNew();
            while (sw.Elapsed.TotalSeconds < secondsToWait)
            {
                ToolResult adbRes = InvokeToolSafe(ADB_EXE, "devices", 1500, false);
                if (!adbRes.TimedOut && Regex.IsMatch(adbRes.Output, @"(?m)^(\S+)\s+device\b"))
                {
                    WriteColor("[+] Sesion ADB USB detectada! Aplicando Interfaz del Firmware Xview Liberado...", ConsoleColor.Green);
                    ExecuteLiberatedXviewFirmwareUiTransformation();
                    return;
                }
                Thread.Sleep(2000);
            }

            if (ScanLocalNetworkForBoxAdb())
            {
                ExecuteLiberatedXviewFirmwareUiTransformation();
            }
            else
            {
                WriteColor("[i] Si acabas de preparar la memoria USB KINGSTON, insertala en la caja para abrir el modo debug/instalador.", ConsoleColor.Yellow);
            }
        }

