            int tick = 0;
            DateTime lastRebootToBl = DateTime.MinValue;

            while (true)
            {
                if (Console.KeyAvailable)
                {
                    var k = Console.ReadKey(true);
                    if (k.Key == ConsoleKey.Escape)
                    {
                        LogEvent("MISION_PRINCIPAL", "Usuario salio del radar con ESC.");
                        return;
                    }
                }

                tick++;

                // 1. Caza directa WorldCup cada 48ms
                if (TryCatchWorldCup48ms())
                {
                    lastRebootToBl = DateTime.Now;
                    continue;
                }

                if ((DateTime.Now - lastRebootToBl).TotalSeconds < 3.2)
                {
                    Thread.Sleep(50);
                    continue;
                }

                // 2. Cada 6 ticks (~300ms), verificar Fastboot y ADB
                if ((tick % 6) == 0)
                {
                    ToolResult fbDevs = InvokeFastbootSafe("devices", 1200, false);
                    if (!fbDevs.TimedOut)
                    {
                        Match mFb = Regex.Match(fbDevs.Output, @"(?m)^(\S+)\s+fastboot");
                        if (mFb.Success)
                        {
                            string fbSn = mFb.Groups[1].Value;
                            ToolResult ping = InvokeFastbootSafe("getvar version-bootloader", 900, false);
                            if (!ping.TimedOut && (
                                ping.Output.IndexOf("version-bootloader", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                ping.Output.IndexOf("OKAY", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                ping.Output.IndexOf("Finished", StringComparison.OrdinalIgnoreCase) >= 0))
                            {
                                ToolResult uCheck = InvokeFastbootSafe("getvar is-userspace", 1200, true);
                                if (Regex.IsMatch(uCheck.Output, @"is-userspace:\s*yes", RegexOptions.IgnoreCase))
                                {
                                    LogEvent("FASTBOOTD_CAUGHT", "Detectado Recovery fastbootd (PID_4EE7 / " + fbSn + ").");
                                    TryFlashInRecoveryFastbootd(fbSn);
                                    lastRebootToBl = DateTime.Now;
                                    continue;
                                }

                                LogEvent("UBOOT_FASTBOOT_CAUGHT", "Detectado U-Boot Fastboot en vivo (PID_0D02 / " + fbSn + ").");
                                Console.WriteLine();
                                WriteColor("[+] Caja atrapada en U-Boot Fastboot en vivo (Serie: " + fbSn + ")!", ConsoleColor.Green);
                                WriteColor("    Reteniendo Watchdog y ejecutando secuencia de desbloqueo limpia...", ConsoleColor.Cyan);

                                InvokeFastbootSafe("flashing get_unlock_ability", 1500, true);
                                InvokeFastbootSafe("flashing unlock_critical", 1500, true);
                                InvokeFastbootSafe("flashing unlock", 1500, true);
                                InvokeFastbootSafe("oem \"watchdog off\"", 1200, true);
                                InvokeFastbootSafe("oem \"setenv lock 10100000;save\"", 1200, true);
                                InvokeFastbootSafe("oem \"setenv otg_device 1;save\"", 1200, true);
                                InvokeFastbootSafe("oem \"saveenv\"", 1200, true);

                                ToolResult unlRes = InvokeFastbootSafe("getvar unlocked", 1500, true);
                                bool isUnlocked = Regex.IsMatch(unlRes.Output, @"unlocked:\s*yes", RegexOptions.IgnoreCase);

                                if (!isUnlocked)
                                {
                                    string dtbPath = Path.Combine(FW_DIR, "dtb.img");
                                    if (File.Exists(dtbPath))
                                    {
                                        ToolResult testWrite = InvokeFastbootSafe("flash _aml_dtb \"" + dtbPath + "\"", 2500, true);
                                        if (!testWrite.TimedOut && testWrite.ExitCode == 0 &&
                                            testWrite.Output.IndexOf("OKAY", StringComparison.OrdinalIgnoreCase) >= 0 &&
                                            testWrite.Output.IndexOf("FAILED", StringComparison.OrdinalIgnoreCase) < 0 &&
                                            testWrite.Output.IndexOf("locked device", StringComparison.OrdinalIgnoreCase) < 0)
                                        {
                                            isUnlocked = true;
                                        }
                                    }
                                }

                                if (isUnlocked)
                                {
                                    LogEvent("FASTBOOT_UNLOCKED", "Bootloader verificado como DESBLOQUEADO (isUnlocked=true).");
                                    Console.WriteLine();
                                    WriteColor("================================================================================", ConsoleColor.Green);
                                    WriteColor(" [OK] BOOTLOADER 100% DESBLOQUEADO (unlocked: yes) Y WATCHDOG RETENIDO          ", ConsoleColor.Green);
                                    WriteColor("================================================================================", ConsoleColor.Green);
                                    WriteColor("  [1] Flashear Firmware Xview Liberado Completo (Particiones + Interfaz DMC.v2.25)", ConsoleColor.Green);
                                    WriteColor("  [2] Inyectar logo + oem + conf + vbmeta + recovery + cache_ext4 y reiniciar", ConsoleColor.Cyan);
                                    WriteColor("  [3] Dejar en Fastboot y volver al menu", ConsoleColor.Gray);
                                    Console.WriteLine();

                                    string next = ReadChoiceWithKeepAlive("Elige 1, 2 o 3", new[] { "1", "2", "3" });
                                    if (next == "1")
                                    {
                                        InvokeSafeAndroid12Flash(true);
                                    }
                                    else if (next == "2")
                                    {
                                        InvokeQuickUnlockPartitionsFlash();
                                        WaitAndCatchAdbAfterReboot(45);
                                    }
                                    break;
                                }
                                else
                                {
                                    bool continueRadar = HandleLockedFastbootInMainMission();
                                    if (continueRadar)
                                    {
                                        lastRebootToBl = DateTime.Now;
                                        continue;
                                    }
                                    else
                                    {
                                        break;
                                    }
                                }
                            }
                        }
                    }

                    // 3. Verificar sesion ADB activa
                    ToolResult adbRes = InvokeToolSafe(ADB_EXE, "devices", 1500, false);
                    if (!adbRes.TimedOut)
                    {
                        if (Regex.IsMatch(adbRes.Output, @"(?m)^(\S+)\s+unauthorized"))
                        {
                            WriteColor("[!] Acepta el cartel 'Permitir Depuracion por USB' en tu TV...", ConsoleColor.Yellow);
                        }
                        else
                        {
                            Match mAdb = Regex.Match(adbRes.Output, @"(?m)^(\S+)\s+device\b");
                            if (mAdb.Success)
                            {
                                string adbId = mAdb.Groups[1].Value;
