                                ExecuteLiberatedXviewFirmwareUiTransformation();
                                break;
                            }
                        }
                    }
                }

                Thread.Sleep(20);
            }

            WriteColor("\nPresiona ENTER para volver al menu: ", ConsoleColor.Gray, false);
            Console.ReadLine();
        }

