        // PREPARACION AUTOMATICA DE MEMORIA USB KINGSTON CON TODA LA INTERFAZ LIBERADA
        // ==============================================================================
        static bool AutoPrepareConnectedUsbDrive(string explicitDriveLetter = null)
        {
            try
            {
                string targetUsb = null;
                if (!string.IsNullOrEmpty(explicitDriveLetter))
                {
                    targetUsb = explicitDriveLetter.Replace(":", "").Replace("\\", "").Trim() + ":\\";
                }
                else
                {
                    var drives = DriveInfo.GetDrives().Where(d => d.DriveType == DriveType.Removable && d.IsReady).ToList();
                    if (drives.Count == 1)
                    {
                        targetUsb = drives[0].Name;
                        WriteColor("[+] Memoria USB detectada automaticamente: " + drives[0].Name + " (" + drives[0].VolumeLabel + ")", ConsoleColor.Green);
                    }
                    else if (drives.Count > 1)
                    {
                        WriteColor("Memorias USB detectadas:", ConsoleColor.Cyan);
                        foreach (var d in drives)
                        {
                            WriteColor(string.Format("  * Unidad {0} ({1} - {2})", d.Name, d.VolumeLabel, d.DriveFormat), ConsoleColor.Green);
                        }
                        WriteColor("Escribe la letra de tu memoria USB (ej. D): ", ConsoleColor.Yellow, false);
                        string drv = (Console.ReadLine() ?? "").Replace(":", "").Replace("\\", "").Trim();
                        if (!string.IsNullOrEmpty(drv)) targetUsb = drv + ":\\";
                    }
                }

                if (string.IsNullOrEmpty(targetUsb) || !Directory.Exists(targetUsb))
                {
                    WriteColor("[!] No se detecto una memoria USB conectada en la PC en este momento.", ConsoleColor.Yellow);
                    return false;
                }

                WriteColor("[*] Copiando llaves externas (factory_update_param.aml + QADEBUG.ini) a " + targetUsb + "...", ConsoleColor.Cyan);
                foreach (string f in Directory.GetFiles(KEYS_DIR))
                {
                    File.Copy(f, Path.Combine(targetUsb, Path.GetFileName(f)), true);
                }

                string usbApkDir = Path.Combine(targetUsb, "INTERFAZ_FIRMWARE_XVIEW_LIBERADO");
                Directory.CreateDirectory(usbApkDir);

                WriteColor("[*] Copiando Suite Completa de Interfaz Firmware Xview Liberado (DMC.v2.25) a la USB...", ConsoleColor.Cyan);
                for (int i = 0; i < LIBERATED_FIRMWARE_UI_APKS.GetLength(0); i++)
                {
                    string apkName = LIBERATED_FIRMWARE_UI_APKS[i, 0];
                    string src = Path.Combine(APKS_DIR, apkName);
                    if (File.Exists(src))
                    {
                        WriteColor("    -> Copiando " + apkName + "...", ConsoleColor.Gray);
                        File.Copy(src, Path.Combine(usbApkDir, apkName), true);
                        // Copiar tambien los launchers principales a la raiz de la USB para acceso rapido
                        if (i < 6)
                        {
                            File.Copy(src, Path.Combine(targetUsb, apkName), true);
                        }
                    }
                }

                WriteColor("[OK] Memoria USB " + targetUsb + " preparada con Llaves de Salto + Interfaz Firmware Xview Liberado!", ConsoleColor.Green);
                LogEvent("USB_PREP", "Memoria USB preparada exitosamente en " + targetUsb);
                return true;
            }
            catch (Exception ex)
            {
                WriteColor("[!] Error preparando USB: " + ex.Message, ConsoleColor.Red);
                return false;
            }
        }

