        // ==============================================================================
        // FLUJO PRINCIPAL AUTOMATICO LIMITADO A LOS 4 PASOS CORTOS:
        //   PASO 1/4: ESCANEANDO LA MEMORIA
        //   PASO 2/4: ENTRANDO EN MODO FASTBOOT
        //   PASO 3/4: INYECTANDO FIRMWARE
        //   PASO 4/4: EXITO TOTAL
        // ==============================================================================
        static void ExecuteFourStepDirectMission()
        {
            LogEvent("MISION_4_PASOS", "=== INICIANDO FLUJO DIRECTO DE 4 PASOS ===");
            Console.WriteLine();

            // --------------------------------------------------------------------------
            // PASO 1/4: ESCANEANDO LA MEMORIA
            // --------------------------------------------------------------------------
            WriteColor("================================================================================", ConsoleColor.Yellow);
            WriteColor(" [PASO 1/4] ESCANEANDO LA MEMORIA...", ConsoleColor.Yellow);
            WriteColor("================================================================================", ConsoleColor.Yellow);

            try
            {
                var usbDrives = DriveInfo.GetDrives().Where(d => d.DriveType == DriveType.Removable && d.IsReady).ToList();
                if (usbDrives.Count > 0)
                {
                    foreach (var d in usbDrives)
                    {
                        WriteColor("  [+] Memoria USB detectada en PC: " + d.Name + " (" + d.VolumeLabel + ") -> Sincronizando llaves...", ConsoleColor.Green);
                        foreach (string f in Directory.GetFiles(KEYS_DIR))
                        {
                            File.Copy(f, Path.Combine(d.Name, Path.GetFileName(f)), true);
                        }
                    }
                }
                else
                {
                    WriteColor("  [+] Memoria USB KINGSTON lista en la caja (con factory_update_param.aml + QADEBUG.ini).", ConsoleColor.Green);
                }
            }
            catch { }

            string superPath = FindSuperImgPath();
            int imgCount = Directory.Exists(FW_DIR) ? Directory.GetFiles(FW_DIR, "*.img").Length : 0;
            int apkCount = Directory.Exists(APKS_DIR) ? Directory.GetFiles(APKS_DIR, "*.apk").Length : 0;
            WriteColor(string.Format("  [OK] Memoria de Firmware verificada: {0} particiones .img + {1} APKs de Interfaz Xview Liberada.", imgCount, apkCount), ConsoleColor.Green);
            if (!string.IsNullOrEmpty(superPath))
            {
                WriteColor("  [OK] Imagen 'super.img' detectada en: " + superPath, ConsoleColor.Green);
            }

            // --------------------------------------------------------------------------
            // PASO 2/4: ENTRANDO EN MODO FASTBOOT
            // --------------------------------------------------------------------------
            Console.WriteLine();
            WriteColor("================================================================================", ConsoleColor.Cyan);
            WriteColor(" [PASO 2/4] ENTRANDO EN MODO FASTBOOT...", ConsoleColor.Cyan);
            WriteColor("================================================================================", ConsoleColor.Cyan);
            WriteColor("  * Esperando senal de la caja (Si esta encendida: desconecta corriente, manten", ConsoleColor.White);
            WriteColor("    presionado RESET y conecta corriente con la memoria USB puesta)...", ConsoleColor.White);

            string caughtSerial = "";
            string caughtMode = ""; // "FASTBOOT" o "ADB"
            DateTime lastJumpToBl = DateTime.MinValue;
            int tick = 0;

            while (true)
            {
                if (Console.KeyAvailable && Console.ReadKey(true).Key == ConsoleKey.Escape)
                {
                    LogEvent("MISION_4_PASOS", "Cancelado por el usuario con ESC.");
                    return;
                }

                tick++;

                // A. Caza directa WorldCup (48ms)
                if (TryCatchWorldCup48ms())
                {
                    lastJumpToBl = DateTime.Now;
                    continue;
                }

                if ((DateTime.Now - lastJumpToBl).TotalSeconds < 2.8)
                {
                    Thread.Sleep(40);
                    continue;
                }

                if ((tick % 5) == 0)
                {
                    // B. Verificar Fastboot (Recovery PID_4EE7 o U-Boot PID_0D02)
                    ToolResult fbDevs = InvokeFastbootSafe("devices", 1000, false);
                    if (!fbDevs.TimedOut)
                    {
                        Match mFb = Regex.Match(fbDevs.Output, @"(?m)^(\S+)\s+fastboot");
                        if (mFb.Success)
                        {
                            string fbSn = mFb.Groups[1].Value;
                            ToolResult ping = InvokeFastbootSafe("getvar version-bootloader", 800, false);
                            if (!ping.TimedOut && (
                                ping.Output.IndexOf("version-bootloader", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                ping.Output.IndexOf("OKAY", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                ping.Output.IndexOf("Finished", StringComparison.OrdinalIgnoreCase) >= 0))
                            {
                                ToolResult uCheck = InvokeFastbootSafe("getvar is-userspace", 1000, true);
                                if (Regex.IsMatch(uCheck.Output, @"is-userspace:\s*yes", RegexOptions.IgnoreCase))
                                {
                                    // Salto INMEDIATO de Recovery Fastbootd (PID_4EE7) a U-Boot Fastboot (PID_0D02) en 1 sola linea!
                                    WriteColor("  [+] Puente Recovery detectado (PID_4EE7 / " + fbSn + ") -> Entrando a Modo Fastboot...", ConsoleColor.Green);
                                    InvokeFastbootSafe("reboot bootloader", 2500, true);
                                    lastJumpToBl = DateTime.Now;
                                    continue;
                                }

                                // Ya estamos en U-Boot Fastboot (PID_0D02)!
                                caughtSerial = fbSn;
                                caughtMode = "FASTBOOT";
                                WriteColor("  [OK] Modo Fastboot Activo y Retenido (Serie: " + caughtSerial + ")!", ConsoleColor.Green);
                                break;
                            }
                        }
                    }

                    // C. Verificar si la caja abrio ADB directo
                    ToolResult adbRes = InvokeToolSafe(ADB_EXE, "devices", 1200, false);
                    if (!adbRes.TimedOut)
                    {
                        Match mAdb = Regex.Match(adbRes.Output, @"(?m)^(\S+)\s+device\b");
                        if (mAdb.Success)
                        {
                            caughtSerial = mAdb.Groups[1].Value;
                            caughtMode = "ADB";
                            WriteColor("  [OK] Puente ADB Activo (" + caughtSerial + ") -> Desbloqueando env y entrando a Fastboot...", ConsoleColor.Green);
                            break;
                        }
                    }
                }

                Thread.Sleep(25);
            }

            // --------------------------------------------------------------------------
            // PASO 3/4: INYECTANDO FIRMWARE
            // --------------------------------------------------------------------------
            Console.WriteLine();
            WriteColor("================================================================================", ConsoleColor.Magenta);
            WriteColor(" [PASO 3/4] INYECTANDO FIRMWARE XVIEW LIBERADO...", ConsoleColor.Magenta);
            WriteColor("================================================================================", ConsoleColor.Magenta);

            if (caughtMode == "ADB")
            {
                ExecuteLiberatedXviewFirmwareUiTransformation();
            }
            else
            {
                // Secuencia automatica de desbloqueo + reconexion en Bootloader (igual al script funcional de B866V2)
                WriteColor("  -> Preparando y desbloqueando registros de escritura U-Boot...", ConsoleColor.Cyan);
                InvokeFastbootSafe("oem \"watchdog off\"", 1200, true);
                InvokeFastbootSafe("flashing get_unlock_ability", 1200, true);
                InvokeFastbootSafe("flashing unlock_critical", 1200, true);
                InvokeFastbootSafe("flashing unlock", 1200, true);
                InvokeFastbootSafe("oem \"'setenv lock 10100000;save\"", 1200, true);
                InvokeFastbootSafe("oem \"setenv lock 10100000;save\"", 1200, true);
                InvokeFastbootSafe("oem \"setenv otg_device 1;save\"", 1200, true);
                InvokeFastbootSafe("oem \"setenv lock 10100000\"", 1200, true);
                InvokeFastbootSafe("oem \"setenv otg_device 1\"", 1200, true);
                InvokeFastbootSafe("oem \"saveenv\"", 1200, true);

                // Recargar el Bootloader (reboot bootloader, NUNCA reboot a Android!) mientras cazamos WorldCup en paralelo
                WriteColor("  -> Recargando tabla del Bootloader en Fastboot...", ConsoleColor.Cyan);
                InvokeFastbootSafe("reboot bootloader", 2500, true);

                Stopwatch swWaitBl = Stopwatch.StartNew();
                while (swWaitBl.Elapsed.TotalSeconds < 12)
                {
                    if (TryCatchWorldCup48ms())
                    {
                        Thread.Sleep(1000);
                    }
                    ToolResult fbRe = InvokeFastbootSafe("devices", 900, false);
