298:                     Task<string> errTask = proc.StandardError.ReadToEndAsync();
299: 
300:                     if (!proc.WaitForExit(timeoutMs))
301:                     {
302:                         try { proc.Kill(); } catch { }
303:                         if (logCmd)
304:                         {
