    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_Free(IntPtr InterfaceHandle);

    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_QueryInterfaceSettings(IntPtr InterfaceHandle, byte AlternateInterfaceNumber, out USB_INTERFACE_DESCRIPTOR UsbAltInterfaceDescriptor);

    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_QueryPipe(IntPtr InterfaceHandle, byte AlternateInterfaceNumber, byte PipeIndex, out WINUSB_PIPE_INFORMATION PipeInformation);

    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_SetPipePolicy(IntPtr InterfaceHandle, byte PipeID, uint PolicyType, uint ValueLength, ref uint Value);

    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_WritePipe(IntPtr InterfaceHandle, byte PipeID, byte[] Buffer, uint BufferLength, out uint LengthTransferred, IntPtr Overlapped);

    [DllImport("winusb.dll", SetLastError = true)]
    public static extern bool WinUsb_ReadPipe(IntPtr InterfaceHandle, byte PipeID, byte[] Buffer, uint BufferLength, out uint LengthTransferred, IntPtr Overlapped);

    [StructLayout(LayoutKind.Sequential)]
    public struct USB_INTERFACE_DESCRIPTOR {
        public byte bLength;
        public byte bDescriptorType;
        public byte bInterfaceNumber;
        public byte bAlternateSetting;
        public byte bNumEndpoints;
        public byte bInterfaceClass;
        public byte bInterfaceSubClass;
        public byte bInterfaceProtocol;
        public byte iInterface;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct WINUSB_PIPE_INFORMATION {
        public int PipeType;
        public byte PipeId;
        public ushort MaximumPacketSize;
        public byte Interval;
    }

    public static void Probe(string path) {
        var h = CreateFile(path, 0xC0000000u, 3, IntPtr.Zero, 3, 0x40000000u, IntPtr.Zero);
        if (h.IsInvalid) {
            Console.WriteLine("CreateFile failed: " + Marshal.GetLastWin32Error());
            return;
        }
        IntPtr iface;
        if (!WinUsb_Initialize(h, out iface)) {
            Console.WriteLine("WinUsb_Initialize failed: " + Marshal.GetLastWin32Error());
            h.Close();
            return;
        }
        USB_INTERFACE_DESCRIPTOR desc;
        WinUsb_QueryInterfaceSettings(iface, 0, out desc);
        Console.WriteLine(string.Format("Interface: Class=0x{0:X2}, SubClass=0x{1:X2}, Prot=0x{2:X2}, Endpoints={3}", desc.bInterfaceClass, desc.bInterfaceSubClass, desc.bInterfaceProtocol, desc.bNumEndpoints));
        byte epIn = 0, epOut = 0;
        for (byte i = 0; i < desc.bNumEndpoints; i++) {
            WINUSB_PIPE_INFORMATION pipe;
            if (WinUsb_QueryPipe(iface, 0, i, out pipe)) {
                Console.WriteLine(string.Format("  Pipe {0}: Id=0x{1:X2}, Type={2}, MaxPkt={3}", i, pipe.PipeId, pipe.PipeType, pipe.MaximumPacketSize));
                if ((pipe.PipeId & 0x80) != 0) epIn = pipe.PipeId;
                else epOut = pipe.PipeId;
            }
        }
        uint timeout = 1000;
        WinUsb_SetPipePolicy(iface, epIn, 3, 4, ref timeout);
        WinUsb_SetPipePolicy(iface, epOut, 3, 4, ref timeout);

        string[] cmds = new string[] { "getvar:version", "getvar:product", "getvar:serialno" };
        foreach (var cmd in cmds) {
            byte[] outBuf = Encoding.ASCII.GetBytes(cmd);
            uint written = 0;
            bool wok = WinUsb_WritePipe(iface, epOut, outBuf, (uint)outBuf.Length, out written, IntPtr.Zero);
            Console.WriteLine("Write '" + cmd + "': ok=" + wok + " written=" + written + " err=" + Marshal.GetLastWin32Error());
            byte[] inBuf = new byte[512];
            uint read = 0;
            bool rok = WinUsb_ReadPipe(iface, epIn, inBuf, (uint)inBuf.Length, out read, IntPtr.Zero);
            Console.WriteLine("Read: ok=" + rok + " read=" + read + " resp='" + Encoding.ASCII.GetString(inBuf, 0, (int)read) + "'");
        }
        WinUsb_Free(iface);
        h.Close();
    }
}
