baudrate=115200
board=franklin_b820c
bootdelay=1
boot_part=boot
recovery_part=recovery
fdt_high=0x20000000
initrd_high=0xFFE00000
loadaddr=0x1080000
dtb_mem_addr=0x1000000

# Estado de bloqueo de Bootloader ZTE (10100000 = Desbloqueado / 10101000 = Bloqueado)
lock=10101000
lock_State=locked

# Parametros de video HDMI e inicializacion CVBS/Mini-AV
outputmode=1080p60hz
hdmimode=1080p60hz
cvbsmode=576cvbs
colorattribute=444,8bit
dolby_status=0
hdr_policy=0

# Configuracion USB OTG / Device Mode (0 = Auto/OTG, 1 = Force Host, 2 = Force Device/ADB)
otg_device=1

# Argumentos pasados al Kernel Linux (bootargs)
initargs=rootfstype=ramfs init=/init console=ttyS0,115200 no_console_suspend earlycon=aml-uart,0xff803000 ramoops.pstore_en=1 ramoops.record_size=0x8000 ramoops.console_size=0x4000

# Secuencia de arranque (verifica USB/SD -> BCB misc -> normal boot)
