start_usb_autoscript=if fatload usb 0 1020000 aml_autoscript; then autoscr 1020000; fi;
storeboot=if imgread kernel ${boot_part} ${loadaddr}; then bootm ${loadaddr}; fi; run update;

# Entrada a modo Burning / WorldCup (MaskROM / Fastboot)
