                        state.UsbHardwareMode = "Recovery Fastbootd Activo (PID_4EE7)";
                        state.RawPid = "4EE7";
                    }
                    else if (devId.IndexOf("PID_0D02", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        state.RawPid = "0D02";
